-- Consent-only events and verified affiliate accounting, preserving previous domains.
CREATE TABLE "AnalyticsSession" ("id" UUID PRIMARY KEY,"tokenHash" CHAR(64) NOT NULL UNIQUE,"visitorHash" CHAR(64) NOT NULL,"consentVersion" VARCHAR(40) NOT NULL,"consentAt" TIMESTAMPTZ(3) NOT NULL,"startedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ(3) NOT NULL,CHECK ("expiresAt">"startedAt"));
CREATE INDEX "AnalyticsSession_startedAt_idx" ON "AnalyticsSession"("startedAt");
CREATE INDEX "AnalyticsSession_visitorHash_idx" ON "AnalyticsSession"("visitorHash");
CREATE INDEX "AnalyticsSession_expiresAt_idx" ON "AnalyticsSession"("expiresAt");
CREATE TABLE "AnalyticsRateLimit" ("key" VARCHAR(80) PRIMARY KEY,"attempts" INTEGER NOT NULL DEFAULT 0,"windowStarted" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("attempts">=0));
CREATE TABLE "AffiliateProgram" ("id" UUID PRIMARY KEY,"slug" VARCHAR(100) NOT NULL UNIQUE,"name" VARCHAR(160) NOT NULL,"allowedHosts" TEXT[] NOT NULL,"signingKeyVariable" VARCHAR(100),"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CHECK (cardinality("allowedHosts") BETWEEN 1 AND 5));
CREATE TABLE "AffiliateLink" ("id" UUID PRIMARY KEY,"programId" UUID NOT NULL REFERENCES "AffiliateProgram"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"toolId" UUID NOT NULL REFERENCES "Tool"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"code" VARCHAR(100) NOT NULL UNIQUE,"destinationUrl" VARCHAR(2048) NOT NULL,"label" VARCHAR(160) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,UNIQUE("id","programId"));
CREATE INDEX "AffiliateLink_toolId_active_idx" ON "AffiliateLink"("toolId","active");
CREATE INDEX "AffiliateLink_programId_idx" ON "AffiliateLink"("programId");
CREATE TABLE "AnalyticsEvent" ("ga4Status" VARCHAR(30) NOT NULL DEFAULT 'NOT_CONFIGURED',"ga4UpdatedAt" TIMESTAMPTZ(3),"id" UUID PRIMARY KEY,"sessionId" UUID NOT NULL REFERENCES "AnalyticsSession"("id") ON DELETE CASCADE ON UPDATE CASCADE,"kind" VARCHAR(40) NOT NULL,"path" VARCHAR(200) NOT NULL,"entityId" VARCHAR(100),"affiliateLinkId" UUID REFERENCES "AffiliateLink"("id") ON DELETE SET NULL ON UPDATE CASCADE,"campaignId" UUID REFERENCES "SponsorshipCampaign"("id") ON DELETE SET NULL ON UPDATE CASCADE,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("kind","entityId"),CHECK ("kind" IN ('PAGE_VIEW','SEARCH','TOOL_VIEW','CAMPAIGN_CLICK','NEWSLETTER_SIGNUP','NEWSLETTER_CONFIRM','SPONSOR_REQUEST','AFFILIATE_CLICK')));
CREATE INDEX "AnalyticsEvent_createdAt_kind_idx" ON "AnalyticsEvent"("createdAt","kind");
CREATE INDEX "AnalyticsEvent_path_createdAt_idx" ON "AnalyticsEvent"("path","createdAt");
CREATE INDEX "AnalyticsEvent_sessionId_createdAt_idx" ON "AnalyticsEvent"("sessionId","createdAt");
CREATE INDEX "AnalyticsEvent_affiliateLinkId_idx" ON "AnalyticsEvent"("affiliateLinkId");
CREATE INDEX "AnalyticsEvent_campaignId_idx" ON "AnalyticsEvent"("campaignId");
CREATE TABLE "AffiliateConversion" ("id" UUID PRIMARY KEY,"programId" UUID NOT NULL,"linkId" UUID NOT NULL,"externalId" VARCHAR(160) NOT NULL,"status" VARCHAR(20) NOT NULL,"commissionMinor" BIGINT NOT NULL,"currency" "Currency" NOT NULL,"occurredAt" TIMESTAMPTZ(3) NOT NULL,"verifiedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("programId","externalId"),FOREIGN KEY("linkId","programId") REFERENCES "AffiliateLink"("id","programId") ON DELETE RESTRICT ON UPDATE CASCADE,CHECK ("status" IN ('CONFIRMED','REVERSED')),CHECK ("commissionMinor">=0));
CREATE INDEX "AffiliateConversion_status_occurredAt_idx" ON "AffiliateConversion"("status","occurredAt");
CREATE INDEX "AffiliateConversion_linkId_idx" ON "AffiliateConversion"("linkId");
CREATE TABLE "AffiliateEvent" ("id" UUID PRIMARY KEY,"programId" UUID NOT NULL REFERENCES "AffiliateProgram"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"externalEventId" VARCHAR(160) NOT NULL,"conversionId" UUID NOT NULL REFERENCES "AffiliateConversion"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"payloadDigest" CHAR(64) NOT NULL,"signedAt" TIMESTAMPTZ(3) NOT NULL,"verifiedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("programId","externalEventId"));
CREATE INDEX "AffiliateEvent_conversionId_idx" ON "AffiliateEvent"("conversionId");
CREATE TABLE "BusinessExpense" ("id" UUID PRIMARY KEY,"label" VARCHAR(160) NOT NULL,"category" VARCHAR(30) NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" "Currency" NOT NULL,"occurredAt" TIMESTAMPTZ(3) NOT NULL,"evidenceRef" VARCHAR(300) NOT NULL,"recordedById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"voidedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CHECK ("amountMinor">0),CHECK ("category" IN ('HOSTING','EMAIL','SOFTWARE','OTHER')));
CREATE INDEX "BusinessExpense_occurredAt_voidedAt_idx" ON "BusinessExpense"("occurredAt","voidedAt");
CREATE TABLE "GrowthExperiment" ("id" UUID PRIMARY KEY,"title" VARCHAR(160) NOT NULL,"hypothesis" VARCHAR(1500) NOT NULL,"path" VARCHAR(200) NOT NULL,"metric" VARCHAR(40) NOT NULL,"status" VARCHAR(20) NOT NULL DEFAULT 'PROPOSED',"createdById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CHECK ("status" IN ('PROPOSED','OBSERVING','COMPLETED','STOPPED')),CHECK ("metric" IN ('PAGE_VIEW','NEWSLETTER_CONFIRM','SPONSOR_REQUEST','AFFILIATE_CLICK')));
CREATE INDEX "GrowthExperiment_status_createdAt_idx" ON "GrowthExperiment"("status","createdAt");
CREATE TABLE "AnalyticsExternalSnapshot" ("id" UUID PRIMARY KEY,"provider" VARCHAR(10) NOT NULL,"rangeStart" TIMESTAMPTZ(3) NOT NULL,"rangeEnd" TIMESTAMPTZ(3) NOT NULL,"data" JSONB NOT NULL,"sourceRef" VARCHAR(300) NOT NULL,"importedById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"importedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("provider" IN ('GA4','GSC')),CHECK ("rangeEnd">"rangeStart"));
CREATE INDEX "AnalyticsExternalSnapshot_provider_importedAt_idx" ON "AnalyticsExternalSnapshot"("provider","importedAt");

-- Grant only the new aggregate read tool to the established CEO profile and invalidate old approvals.
UPDATE "Agent" SET "allowedTools"=array_append("allowedTools",'analytics_summary'),"promptVersion"="promptVersion"+1,"updatedAt"=CURRENT_TIMESTAMP WHERE identifier='team-ceo' AND role='CEO' AND cardinality("allowedTools")=3 AND "allowedTools" @> ARRAY['business_metrics','team_reports','delegate_tasks']::text[];
